package com.airesumebuilder.feature.pdf.controller;
import com.airesumebuilder.feature.pdf.service.PdfService;import com.airesumebuilder.security.CurrentUser;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/resumes/{resumeId}/pdf") public class ResumePdfController{private final PdfService pdf;private final CurrentUser user;public ResumePdfController(PdfService pdf,CurrentUser user){this.pdf=pdf;this.user=user;}@PostMapping(produces=MediaType.APPLICATION_PDF_VALUE)public ResponseEntity<byte[]>export(@PathVariable long resumeId){var result=pdf.generate(user.email(),resumeId);return ResponseEntity.ok().contentType(MediaType.APPLICATION_PDF).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+result.fileName()+"\"").contentLength(result.content().length).body(result.content());}}
